-- Studio-Masons ERP — Design brief template seed (imported from the office
-- questionnaires). Run AFTER 0006_design_department.sql. Idempotent: re-running
-- is a no-op once each template already has a published v1. Edit further in the
-- in-app template editor (which publishes new versions).

do $$
declare v_tpl uuid; v_ver uuid; v_sec uuid;
begin
  select id into v_tpl from public.design_templates where key='interior_commercial';
  if not exists (select 1 from public.design_template_versions where template_id=v_tpl) then
  end if;
end $$;

do $$
